fn insert_nested(root: Map[String, Json], path: Array[String], value: Json, ...) {
  let mut table = root
  // Navigate to the parent table
  for i = 0; i < path.length() - 1; i = i + 1 {
    let key = path[i]
    match table.get(key) {
      Some(Table(inner)) => table = inner  // but Json isn't a variant I can destructure...
      None => {
        let new_table : Map[String, Json] = {}
        table[key] = Json::object(new_table)
        table = new_table
      }
      _ => raise ParseError(...) // key already exists as non-table
    }
  }
  // Now insert at the final key
  let final_key = path[path.length() - 1]
  if table.contains(final_key) {
    raise DuplicateKey(...)
  }
  table[final_key] = value
}
