{"content": "///|
/// Internal parser state.
struct Parser {
  input : String
  mut pos : Int
  mut line : Int
  mut col : Int
}

///|
fn Parser::new(input : String) -> Parser {
  { input, pos: 0, line: 1, col: 1 }
}

///|
fn Parser::eof(self : Parser) -> Bool {
  self.pos >= self.input.length()
}

///|
/// Peek at the current character without consuming it.
fn Parser::peek(self : Parser) -> Char? {
  self.input.get_char(self.pos)
}

///|
/// Consume and return the current character.
fn Parser::advance(self : Parser) -> Char? {
  let ch = self.input.get_char(self.pos)
  match ch {
    None => None
    Some(c) => {
      self.pos += 1
      if c == '\n' {
        self.line += 1
        self.col = 1
      } else {
        self.col += 1
      }
      Some(c)
    }
  }
}

///|
/// Skip whitespace (spaces and tabs) but not newlines.
fn Parser::skip_horizontal_whitespace(self : Parser) -> Unit {
  while self.peek() is Some(' ') || self.peek() is Some('\t') {
    self.advance() |> ignore
  }
}

///|
/// Skip a comment line (from '#' to end of line).
fn Parser::skip_comment(self : Parser) -> Unit {
  while self.peek() is Some(c) && c != '\n' {
    self.advance() |> ignore
  }
}

///|
/// Skip blank lines, comments, and whitespace.
/// Returns true if we're at EOF after skipping.
fn Parser::skip_blanks_and_comments(self : Parser) -> Unit {
  while !self.eof() {
    self.skip_horizontal_whitespace()
    match self.peek() {
      Some('\n') => self.advance() |> ignore
      Some('#') => self.skip_comment()
      _ => return
    }
  }
}

///|
/// Get the remaining line (for error messages).
fn Parser::current_line_snippet(self : Parser) -> String {
  let start = self.pos
  let mut end = start
  while end < self.input.length() {
    let ch = self.input[end]
    if ch == ('\n' : UInt16) {
      break
    }
    end += 1
  }
  // Go back to find line start
  let mut line_start = start
  while line_start > 0 {
    let ch = self.input[line_start - 1]
    if ch == ('\n' : UInt16) {
      break
    }
    line_start -= 1
  }
  let line_str = self.input[line_start:end].to_owned()
  line_str
}

///|
/// Raise a parse error at the current position.
fn Parser::parse_error(self : Parser, message : String) -> Never raise TomlError {
  raise TomlError::ParseError(line=self.line, col=self.col, message~)
}

///|
/// Raise a duplicate key error at the current position.
fn Parser::duplicate_key_error(self : Parser, key : String) -> Never raise TomlError {
  raise TomlError::DuplicateKey(line=self.line, col=self.col, key~)
}

///|
/// Parse a complete TOML document into a Json object.
fn Parser::parse_document(self : Parser) -> @json.Json raise TomlError {
  let root : Map[String, @json.Json] = {}
  let mut current_path : Array[String] = []

  self.skip_blanks_and_comments()

  while !self.eof() {
    self.skip_horizontal_whitespace()
    if self.eof() {
      break
    }
    match self.peek() {
      Some('[') => {
        // Table header
        current_path = self.parse_table_header()
      }
      Some('#') => {
        self.skip_comment()
      }
      Some('\n') => {
        self.advance() |> ignore
      }
      _ => {
        // Key-value pair
        self.parse_keyval(root, current_path)
      }
    }
    self.skip_blanks_and_comments()
  }

  @json.Json::object(root)
}

///|
/// Parse a table header like `[foo]` or `[foo.bar.baz]`.
/// Returns the path as an array of key strings.
fn Parser::parse_table_header(self : Parser) -> Array[String] raise TomlError {
  // Consume '['
  self.advance() |> ignore
  let keys = self.parse_dotted_key()
  // Expect ']'
  match self.peek() {
    Some(']') => self.advance() |> ignore
    _ => self.parse_error("expected ']' to close table header")
  }
  // Skip trailing whitespace and comment to end of line
  self.skip_to_eol()
  keys
}

///|
/// Skip to end of line (consuming optional comment and newline).
fn Parser::skip_to_eol(self : Parser) -> Unit {
  self.skip_horizontal_whitespace()
  match self.peek() {
    Some('#') => self.skip_comment()
    _ => ()
  }
  match self.peek() {
    Some('\n') => self.advance() |> ignore
    _ => ()
  }
}

///|
/// Parse a dotted key like `a.b.c` or a bare key like `foo`.
/// Returns the key components as an array.
fn Parser::parse_dotted_key(self : Parser) -> Array[String] raise TomlError {
  let keys : Array[String] = []
  keys.push(self.parse_simple_key())
  while self.peek() == Some('.') {
    self.advance() |> ignore // consume '.'
    keys.push(self.parse_simple_key())
  }
  keys
}

///|
/// Parse a simple key (bare key or quoted string).
fn Parser::parse_simple_key(self : Parser) -> String raise TomlError {
  self.skip_horizontal_whitespace()
  match self.peek() {
    Some('"') => self.parse_basic_string(),
    Some('\'') => self.parse_literal_string(),
    _ => self.parse_bare_key(),
  }
}

///|
/// Parse a bare key (unquoted alphanumeric/underscore/dash).
fn Parser::parse_bare_key(self : Parser) -> String raise TomlError {
  let start = self.pos
  while match self.peek() {
    Some(c) => c.is_ascii_alphanumeric() || c == '_' || c == '-',
    None => false,
  } {
    self.advance() |> ignore
  }
  if self.pos == start {
    // Try to provide a useful error
    let found = match self.peek() {
      Some(c) => "'\{c}'"
      None => "end of input"
    }
    self.parse_error("expected a key but found \{found}")
  }
  self.input[start:self.pos].to_owned()
}

///|
/// Parse a key-value pair and insert into the table at the given path.
fn Parser::parse_keyval(
  self : Parser,
  root : Map[String, @json.Json],
  table_path : Array[String],
) -> Unit raise TomlError {
  let key_start_line = self.line
  let key_start_col = self.col
  let keys = self.parse_dotted_key()

  self.skip_horizontal_whitespace()
  // Expect '='
  match self.peek() {
    Some('=') => self.advance() |> ignore
    _ => self.parse_error("expected '=' after key")
  }
  self.skip_horizontal_whitespace()

  let value = self.parse_value()

  self.skip_to_eol()

  // Navigate to the target table, creating nested tables as needed
  let mut table = root
  let full_path = table_path + keys
  let last_idx = full_path.length() - 1

  for i = 0; i < last_idx; i = i + 1 {
    let key = full_path[i]
    match table.get(key) {
      Some(obj) => match obj {
        @json.Json::Object(inner) => table = inner
        _ => self.parse_error("key '\{key}' is not a table but is used as one")
      }
      None => {
        let new_table : Map[String, @json.Json] = {}
        table[key] = @json.Json::object(new_table)
        table = new_table
      }
    }
  }

  // Insert the value at the final key
  let final_key = full_path[last_idx]
  if table.contains(final_key) {
    raise TomlError::DuplicateKey(
      line=key_start_line,
      col=key_start_col,
      key=final_key,
    )
  }
  table[final_key] = value
}

///|
/// Parse a TOML value.
fn Parser::parse_value(self : Parser) -> @json.Json raise TomlError {
  self.skip_horizontal_whitespace()
  match self.peek() {
    Some('"') => @json.Json::string(self.parse_basic_string()),
    Some('\'') => @json.Json::string(self.parse_literal_string()),
    Some('[') => self.parse_array(),
    Some('t') | Some('f') => @json.Json::boolean(self.parse_boolean()),
    Some(c) if c.is_ascii_digit() || c == '+' || c == '-' =>
      @json.Json::number(self.parse_integer().to_double()),
    _ => self.parse_error("expected a value"),
  }
}

///|
/// Parse a basic string (double-quoted) with escape sequences.
fn Parser::parse_basic_string(self : Parser) -> String raise TomlError {
  // Consume opening '"'
  self.advance() |> ignore
  let buf = StringBuilder::new()
  while self.peek() is Some(c) && c != '"' {
    if c == '\\' {
      self.advance() |> ignore // consume backslash
      match self.peek() {
        Some('"') => {
          buf.write_char('"')
          self.advance() |> ignore
        }
        Some('\\') => {
          buf.write_char('\\')
          self.advance() |> ignore
        }
        Some('n') => {
          buf.write_char('\n')
          self.advance() |> ignore
        }
        Some('t') => {
          buf.write_char('\t')
          self.advance() |> ignore
        }
        Some(esc) => self.parse_error("unknown escape sequence '\\\{esc}'"),
        None => self.parse_error("unexpected end of input in string"),
      }
    } else if c == '\n' {
      self.parse_error("unexpected newline in basic string")
    } else {
      buf.write_char(c)
      self.advance() |> ignore
    }
  }
  // Consume closing '"'
  match self.peek() {
    Some('"') => self.advance() |> ignore
    _ => self.parse_error("unterminated string literal"),
  }
  buf.to_string()
}

///|
/// Parse a literal string (single-quoted) with no escapes.
fn Parser::parse_literal_string(self : Parser) -> String raise TomlError {
  // Consume opening '\''
  self.advance() |> ignore
  let start = self.pos
  while self.peek() is Some(c) && c != '\'' {
    if c == '\n' {
      self.parse_error("unexpected newline in literal string")
    }
    self.advance() |> ignore
  }
  let s = self.input[start:self.pos].to_owned()
  // Consume closing '\''
  match self.peek() {
    Some('\'') => self.advance() |> ignore
    _ => self.parse_error("unterminated literal string"),
  }
  s
}

///|
/// Parse an integer value (decimal).
fn Parser::parse_integer(self : Parser) -> Int raise TomlError {
  let start = self.pos
  // Optional sign
  match self.peek() {
    Some('+') | Some('-') => self.advance() |> ignore
    _ => ()
  }
  // Digits
  if self.peek() is Some(c) && !c.is_ascii_digit() {
    self.parse_error("expected a digit")
  }
  while self.peek() is Some(c) && c.is_ascii_digit() {
    self.advance() |> ignore
  }
  // Optional underscore separators - we just skip them
  // Actually, for simplicity, we don't handle underscores here
  let num_str = self.input[start:self.pos]
  match num_str {
    "0" => 0,
    _ if num_str[0] == ('+' : UInt16) => {
      // For simplicity, parse manually
      let s = num_str[1:].to_owned()
      parse_int_from_string(s)
    }
    _ if num_str[0] == ('-' : UInt16) => {
      let s = num_str[1:].to_owned()
      -parse_int_from_string(s)
    }
    _ => parse_int_from_string(num_str.to_owned())
  }
}

///|
fn parse_int_from_string(s : String) -> Int {
  let mut n : Int = 0
  for ch in s {
    n = n * 10 + (ch.to_int() - '0'.to_int())
  }
  n
}

///|
/// Parse a boolean value (true or false).
fn Parser::parse_boolean(self : Parser) -> Bool raise TomlError {
  if self.input[self.pos:self.pos + 4] == "true" {
    for _ = 0; _ < 4; _ = _ + 1 {
      self.advance() |> ignore
    }
    true
  } else if self.input[self.pos:self.pos + 5] == "false" {
    for _ = 0; _ < 5; _ = _ + 1 {
      self.advance() |> ignore
    }
    false
  } else {
    self.parse_error("expected 'true' or 'false'")
  }
}

///|
/// Parse an array value like `[1, 2, 3]`.
fn Parser::parse_array(self : Parser) -> @json.Json raise TomlError {
  // Consume '['
  self.advance() |> ignore
  let arr : Array[@json.Json] = []

  self.skip_horizontal_whitespace()
  // Check for empty array
  if self.peek() == Some(']') {
    self.advance() |> ignore
    return @json.Json::array(arr)
  }

  // Parse first value
  arr.push(self.parse_value())

  // Parse remaining values
  while true {
    self.skip_horizontal_whitespace()
    match self.peek() {
      Some(',') => {
        self.advance() |> ignore
        self.skip_horizontal_whitespace()
        // Allow trailing comma
        if self.peek() == Some(']') {
          self.advance() |> ignore
          break
        }
        arr.push(self.parse_value())
      }
      Some(']') => {
        self.advance() |> ignore
        break
      }
      Some('#') => {
        // Comment inside array - skip to end of line
        self.skip_comment()
        self.skip_horizontal_whitespace()
        match self.peek() {
          Some(',') => {
            self.advance() |> ignore
            self.skip_horizontal_whitespace()
            if self.peek() == Some(']') {
              self.advance() |> ignore
              break
            }
            arr.push(self.parse_value())
          }
          Some(']') => {
            self.advance() |> ignore
            break
          }
          _ => self.parse_error("expected ',' or ']' in array")
        }
      }
      _ => self.parse_error("expected ',' or ']' in array"),
    }
  }

  @json.Json::array(arr)
}
