}

///|
/// Raise a parse error at the current position.
fn[T] Parser::parse_error(self : Parser, message : String) -> T raise TomlError {
  raise TomlError::ParseError(line=self.line, col=self.col, message~)
}

///|
/// Raise a duplicate key error at the current position.
fn[T] Parser::duplicate_key_error(self : Parser, key : String) -> T raise TomlError {
  raise TomlError::DuplicateKey(line=self.line, col=self.col, key~)
}

///|
/// Parse a complete TOML document into a Json object.
fn Parser::parse_document(self : Parser) -> Json raise TomlError {
  let root : Map[String, Json] = {}
  let mut current_path : Array[String] = []

  self.skip_blanks_and_comments()

  while !self.eof() {
    self.skip_horizontal_whitespace()
    if self.eof() {
      break
    }
    match self.peek() {
      Some('[') => {
        // Table header
        current_path = self.parse_table_header()
      }
      Some('#') => {
        self.skip_comment()
      }
      Some('\n') => {
        self.advance() |> ignore
      }
      _ => {
        // Key-value pair
        self.parse_keyval(root, current_path)
      }
    }
    self.skip_blanks_and_comments()
  }

  Json::object(root)
}

///|
/// Parse a table header like `[foo]` or `[foo.bar.baz]`.
/// Returns the path as an array of key strings.
fn Parser::parse_table_header(self : Parser) -> Array[String] raise TomlError {
  // Consume '['
  self.advance() |> ignore
  let keys = self.parse_dotted_key()
  // Expect ']'
  match self.peek() {
    Some(']') => self.advance() |> ignore
    _ => self.parse_error("expected ']' to close table header")
  }
  // Skip trailing whitespace and comment to end of line
  self.skip_to_eol()
  keys
}

///|
/// Skip to end of line (consuming optional comment and newline).
fn Parser::skip_to_eol(self : Parser) -> Unit {
  self.skip_horizontal_whitespace()
  match self.peek() {
    Some('#') => self.skip_comment()
    _ => ()
  }
  match self.peek() {
    Some('\n') => self.advance() |> ignore
    _ => ()
  }
}

///|
/// Parse a dotted key like `a.b.c` or a bare key like `foo`.
/// Returns the key components as an array.
fn Parser::parse_dotted_key(self : Parser) -> Array[String] raise TomlError {
  let keys : Array[String] = []
  keys.push(self.parse_simple_key())
  while self.peek() == Some('.') {
    self.advance() |> ignore // consume '.'
    keys.push(self.parse_simple_key())
  }
  keys
}

///|
/// Parse a simple key (bare key or quoted string).
fn Parser::parse_simple_key(self : Parser) -> String raise TomlError {
  self.skip_horizontal_whitespace()
  match self.peek() {
    Some('"') => self.parse_basic_string()
    Some('\'') => self.parse_literal_string()
    _ => self.parse_bare_key()
  }
}

///|
/// Parse a bare key (unquoted alphanumeric/underscore/dash).
fn Parser::parse_bare_key(self : Parser) -> String raise TomlError {
  let start = self.pos
  // Continue while the current character is a valid bare-key character
  while !self.eof() {
    match self.peek() {
      Some(c) => {
        if c.is_alphabetic() || c.is_digit() || c == '_' || c == '-' {
          self.advance() |> ignore
        } else {
          break
        }
      }
      None => break
    }
  }
  if self.pos == start {
    let found = match self.peek() {
      Some(c) => "'\{c}'"
      None => "end of input"
    }
    self.parse_error("expected a key but found \{found}")
  }
  self.input[start:self.pos].to_owned()
}

///|
/// Parse a key-value pair and insert into the table at the given path.
fn Parser::parse_keyval(
  self : Parser,
  root : Map[String, Json],
  table_path : Array[String],
) -> Unit raise TomlError {
  let key_start_line = self.line
  let key_start_col = self.col
  let keys = self.parse_dotted_key()

  self.skip_horizontal_whitespace()
  // Expect '='
  match self.peek() {
    Some('=') => self.advance() |> ignore
    _ => self.parse_error("expected '=' after key")
  }
  self.skip_horizontal_whitespace()

  let value = self.parse_value()

  self.skip_to_eol()

  // Navigate to the target table, creating nested tables as needed
  let mut table = root
  let full_path = table_path + keys
  let last_idx = full_path.length() - 1

  for i in 0..<last_idx {
    let key = full_path[i]
    match table.get(key) {
      Some(obj) => match obj {
        Json::Object(inner) => table = inner
        _ => self.parse_error("key '\{key}' is not a table but is used as one")
      }
      None => {
        let new_table : Map[String, Json] = {}
        table[key] = Json::object(new_table)
        table = new_table
      }
    }
  }

  // Insert the value at the final key
  let final_key = full_path[last_idx]
  if table.contains(final_key) {
    raise TomlError::DuplicateKey(
      line=key_start_line,
      col=key_start_col,
      key=final_key,
    )
  }
  table[final_key] = value
}

///|
/// Parse a TOML value.
fn Parser::parse_value(self : Parser) -> Json raise TomlError {
  self.skip_horizontal_whitespace()
  match self.peek() {
    Some('"') => Json::string(self.parse_basic_string())
    Some('\'') => Json::string(self.parse_literal_string())
    Some('[') => self.parse_array()
    Some('t') | Some('f') => Json::boolean(self.parse_boolean())
    Some(c) => {
      if c.is_digit() || c == '+' || c == '-' {
        Json::number(self.parse_integer().to_double())
      } else {
        self.parse_error("expected a value")
      }
    }
    None => self.parse_error("unexpected end of input")
  }
}

///|
/// Parse a basic string (double-quoted) with escape sequences.
fn Parser::parse_basic_string(self : Parser) -> String raise TomlError {
  // Consume opening '"'
  self.advance() |> ignore
  let buf = StringBuilder::new()
  while self.peek() is Some(c) && c != '"' {
    if c == '\\' {
      self.advance() |> ignore // consume backslash
      match self.peek() {
        Some('"') => {
          buf.write_char('"')
          self.advance() |> ignore
        }
        Some('\\') => {
          buf.write_char('\\')
          self.advance() |> ignore
        }
        Some('n') => {
          buf.write_char('\n')
          self.advance() |> ignore
        }
        Some('t') => {
          buf.write_char('\t')
          self.advance() |> ignore
        }
        Some(esc) => self.parse_error("unknown escape sequence '\\\{esc}'")
        None => self.parse_error("unexpected end of input in string")
      }
    } else if c == '\n' {
      self.parse_error("unexpected newline in basic string")
    } else {
      buf.write_char(c)
      self.advance() |> ignore
    }
  }
  // Consume closing '"'
  match self.peek() {
    Some('"') => self.advance() |> ignore
    _ => self.parse_error("unterminated string literal")
  }
  buf.to_string()
}

///|
/// Parse a literal string (single-quoted) with no escapes.
fn Parser::parse_literal_string(self : Parser) -> String raise TomlError {
  // Consume opening '\''
  self.advance() |> ignore
  let start = self.pos
  while self.peek() is Some(c) && c != '\'' {
    if c == '\n' {
      self.parse_error("unexpected newline in literal string")
    }
    self.advance() |> ignore
  }
  let s = self.input[start:self.pos].to_owned()
  // Consume closing '\''
  match self.peek() {
    Some('\'') => self.advance() |> ignore
    _ => self.parse_error("unterminated literal string")
  }
  s
}

///|
/// Parse an integer value (decimal).
fn Parser::parse_integer(self : Parser) -> Int raise TomlError {
  let start = self.pos
  // Optional sign
  match self.peek() {
    Some('+') | Some('-') => self.advance() |> ignore
    _ => ()
  }
  // Digits
  match self.peek() {
    Some(c) => {
      if !c.is_digit() {
        self.parse_error("expected a digit")
      }
    }
    None => self.parse_error("expected a digit but found end of input")
  }
  while self.peek() is Some(c) && c.is_digit() {
    self.advance() |> ignore
  }
  let num_str = self.input[start:self.pos]
  parse_int_from_string(num_str.to_owned())
}

///|
fn parse_int_from_string(s : String) -> Int {
  let mut n : Int = 0
  let mut sign : Int = 1
  let mut i = 0
  // handle sign
  if s.length() > 0 && s[0] == ('+' : UInt16) {
    i = 1
  } else if s.length() > 0 && s[0] == ('-' : UInt16) {
    sign = -1
    i = 1
  }
  for ch in s[i:] {
    n = n * 10 + (ch.to_int() - '0'.to_int())
  }
  n * sign
}

///|
/// Parse a boolean value (true or false).
fn Parser::parse_boolean(self : Parser) -> Bool raise TomlError {
  if self.pos + 4 <= self.input.length() && self.input[self.pos:self.pos + 4] == "true" {
    self.pos += 4
    self.col += 4
    true
  } else if self.pos + 5 <= self.input.length() && self.input[self.pos:self.pos + 5] == "false" {
    self.pos += 5
    self.col += 5
    false
  } else {
    self.parse_error("expected 'true' or 'false'")
  }
}

///|
/// Parse an array value like `[1, 2, 3]`.
fn Parser::parse_array(self : Parser) -> Json raise TomlError {
  // Consume '['
  self.advance() |> ignore
  let arr : Array[Json] = []

  self.skip_horizontal_whitespace()
  // Check for empty array
  if self.peek() == Some(']') {
    self.advance() |> ignore
    return Json::array(arr)
  }

  // Parse first value
  arr.push(self.parse_value())

  // Parse remaining values
  while true {
    self.skip_horizontal_whitespace()
    match self.peek() {
      Some(',') => {
        self.advance() |> ignore
        self.skip_horizontal_whitespace()
        // Allow trailing comma
        if self.peek() == Some(']') {
          self.advance() |> ignore
          break
        }
        arr.push(self.parse_value())
      }
      Some(']') => {
        self.advance() |> ignore
        break
      }
      Some('#') => {
        // Comment inside array - skip to end of line
        self.skip_comment()
        self.skip_horizontal_whitespace()
        match self.peek() {
          Some(',') => {
            self.advance() |> ignore
            self.skip_horizontal_whitespace()
            if self.peek() == Some(']') {
              self.advance() |> ignore
              break
            }
            arr.push(self.parse_value())
          }
          Some(']') => {
            self.advance() |> ignore
            break
          }
          _ => self.parse_error("expected ',' or ']' in array")
        }
      }
      _ => self.parse_error("expected ',' or ']' in array")
    }
  }

  Json::array(arr)
}
