/// TOML parsing error types.
pub(all) suberror TomlError {
  /// A generic parse error with position information.
  ParseError(line~ : Int, col~ : Int, message~ : String)
  /// A duplicate key was found in the same table.
  DuplicateKey(line~ : Int, col~ : Int, key~ : String)
} derive(Debug, Eq, ToJson)

///|
/// Parse a TOML string into a `Json` value.
///
/// # Example
/// ```mbt check
/// test {
///   let result = @tomljson.parse("key = 42")
///   let json_str = result.stringify()
///   inspect(json_str, content="{\"key\":42}")
/// }
/// ```
///
/// # Errors
/// Raises `TomlError` on parse errors or duplicate keys.
pub fn parse(input : String) -> Json raise TomlError {
  let p = Parser::new(input)
  p.parse_document()
}
