/// Get the remaining line (for error messages).
fn Parser::current_line_snippet(self : Parser) -> String {
  let start = self.pos
  let mut end = start
  while end < self.input.length() {
    let ch = self.input[end]
    if ch == ('\n' : UInt16) {
      break
    }
    end += 1
  }
  // Go back to find line start
  let mut line_start = start
  while line_start > 0 {
    let ch = self.input[line_start - 1]
    if ch == ('\n' : UInt16) {
      break
    }
    line_start -= 1
  }
  self.input[line_start:end].to_owned()
}

