/// CLI that parses TOML and prints JSON.
async fn main {
  let matches = @argparse.Command(
    "tomljson",
    about="Convert TOML to JSON.",
    flags=[
      @argparse.FlagArg("stdin", long="stdin", about="Read TOML from stdin"),
    ],
    positionals=[
      @argparse.PositionArg(
        "file",
        about="TOML file to parse",
        num_args=@argparse.ValueRange(lower=0),
      ),
    ],
  ).parse() catch {
    _ => {
      @stdio.stderr.write("Error: invalid arguments\n")
      return
    }
  }

  let use_stdin = matches.flags.get("stdin") is Some(true)

  let input = try {
    match matches.values {
      { "file": files, .. } => {
        if !use_stdin && files.length() > 0 {
          let data = @fs.read_file(files[0])
          data.text()
        } else {
          @stdio.stdin.read_all().text()
        }
      }
      _ => @stdio.stdin.read_all().text()
    }
  } catch {
    _ => {
      @stdio.stderr.write("Error: failed to read input\n")
      return
    }
  }

  let json = @lib.parse(input) catch {
    err => {
      @stdio.stderr.write("Error: \{err}\n")
      return
    }
  }

  @stdio.stdout.write(json.stringify())
  @stdio.stdout.write("\n")
}
